    /** A steward rejects a PENDING claim with a reason: it is OPEN again, still bound by its person's last
     *  statement if that statement included it. Refused for a clerk, for a claim that is not PENDING and for one
     *  due by inside a closed period. */
    @Transactional
    public Claim reject(String sheetId, String user, long id, String reason) {
        sheets.load(sheetId, user);
        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
        Claim claim = pendingClaim(sheetId, user, id);
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
        Rollup.Figures before = rollup.of(sheetId);
        claim.setStatus(ClaimStatus.OPEN);
        claim.logStatus(user, sheet.getToday(), shownDue(sheet, claim, person));
        Claim changed = claims.saveAndFlush(claim);
        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_REJECTED", user, person, changed, changed.getNumber())
                + " reason=" + reason.trim());
        rollup.recordChanges(sheetId, user, before);
        return changed;
    }
    });
  }

  protected reasonChanged(c: ClaimView, reason: string): void {
    this.rejectReasons.update((reasons) => ({ ...reasons, [c.id]: reason }));
    if (this.claimError()?.id === c.id) this.claimError.set(null);
  }

  protected reject(c: ClaimView): void {
    this.claimError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const reason = (this.rejectReasons()[c.id] ?? '').trim().replace(/\s+/g, ' ');
    if (reason === '') {
      this.claimError.set({ id: c.id, message: 'Type why the claim is rejected.' });
      return;
    }
    this.api.reject(sheet.id, c.id, reason).subscribe({
      next: (saved) => {
        this.rejectReasons.update((reasons) => ({ ...reasons, [c.id]: '' }));
        this.saved.emit(saved);
      },
      error: (err: unknown) => this.claimError.set({
        id: c.id,
        message: err instanceof HttpErrorResponse && err.status === 403
          ? 'Only a steward or the approver of this person can reject a claim.'
          : this.refusal(err, c, 'rejected'),
      }),
    });
  }

  }

  /** Why approving or rejecting a claim was refused, other than by who asked. */
  private refusal(err: unknown, c: ClaimView, done: string): string {
    return err instanceof HttpErrorResponse && err.status === 423
      ? 'This claim is due by inside a closed period.'
      : err instanceof HttpErrorResponse && err.status === 428
        ? UNPROVEN
      : err instanceof HttpErrorResponse && err.status === 400
        ? 'Type why the claim is rejected.'
        : `A ${c.status} claim cannot be ${done}; only a PENDING one can.`;
  }

  protected fieldId(field: string): string {
    return `claim-form-${field}-${this.personId()}`;
  }

